 $mode=$il.DeclareLocal([int]);$normal=$il.DefineLabel();$nonNegative=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields[$(if($write){'WriteMode'}else{'CountMode'})]);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$mode)
 if($write){$skip=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ble,$skip);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,42);$il.Emit($(if($abstract.Name -eq 'GetBytes'){[Reflection.Emit.OpCodes]::Stelem_I1}else{[Reflection.Emit.OpCodes]::Stelem_I2}));$il.MarkLabel($skip)}
 $il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'array callback failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($normal);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Multiplier);$il.Emit([Reflection.Emit.OpCodes]::Mul);$il.Emit([Reflection.Emit.OpCodes]::Ret)
 }else{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ret)};$builder.DefineMethodOverride($method,$abstract)}
$arrayBridges=@{};
foreach($direction in @('encoder','decoder')){$base=if($direction -eq 'encoder'){[Text.Encoder]}else{[Text.Decoder]};$sourceValue=if($direction -eq 'encoder'){[char[]]}else{[byte[]]};$output=if($direction -eq 'encoder'){[byte[]]}else{[char[]]};$argsTypes=[type[]]@($base,$sourceValue,[int],[int],$output,[int],[int],[bool],[int[]],[bool[]]);$nativeArgs=[type[]]@($sourceValue,[int],[int],$output,[int],[int],[bool],[int].MakeByRefType(),[int].MakeByRefType(),[bool].MakeByRefType());foreach($alias in @($false,$true)){$bridge=[Reflection.Emit.DynamicMethod]::new(('GenericConvert'+$direction+$alias),[void],$argsTypes);$il=$bridge.GetILGenerator();foreach($i in 0..7){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};foreach($i in 0..1){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]8);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$(if($alias){0}else{$i}));$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int])};$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]9);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[bool]);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$base.GetMethod('Convert',$nativeArgs));$il.Emit([Reflection.Emit.OpCodes]::Ret);$action=[type]'System.Action`10';$arrayBridges[$direction+[string]$alias]=$bridge.CreateDelegate($action.MakeGenericType($argsTypes))}}
$spanBridges=@{};
foreach($direction in @('encoder','decoder')){$base=if($direction -eq 'encoder'){[Text.Encoder]}else{[Text.Decoder]};$sourceElement=if($direction -eq 'encoder'){[char]}else{[byte]};$targetElement=if($direction -eq 'encoder'){[byte]}else{[char]};$sourceArray=$sourceElement.MakeArrayType();$targetArray=$targetElement.MakeArrayType();$roDefinition=[type]'System.ReadOnlySpan`1';$spanDefinition=[type]'System.Span`1';$ro=$roDefinition.MakeGenericType([type[]]@($sourceElement));$span=$spanDefinition.MakeGenericType([type[]]@($targetElement));$argsTypes=[type[]]@($base,$sourceArray,[int],[int],$targetArray,[int],[int],[bool],[int[]],[bool[]]);$nativeArgs=[type[]]@($ro,$span,[bool],[int].MakeByRefType(),[int].MakeByRefType(),[bool].MakeByRefType());foreach($alias in @($false,$true)){$bridge=[Reflection.Emit.DynamicMethod]::new(('ConvertSpan'+$direction+$alias),[void],$argsTypes);$il=$bridge.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$ro.GetConstructor([type[]]@($sourceArray,[int],[int])));foreach($i in 4..6){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};$il.Emit([Reflection.Emit.OpCodes]::Newobj,$span.GetConstructor([type[]]@($targetArray,[int],[int])));$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]7);foreach($i in 0..1){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]8);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$(if($alias){0}else{$i}));$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int])};$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]9);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[bool]);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$base.GetMethod('Convert',$nativeArgs));$il.Emit([Reflection.Emit.OpCodes]::Ret);$action=[type]'System.Action`10';$spanBridges[$direction+[string]$alias]=$bridge.CreateDelegate($action.MakeGenericType($argsTypes))}}

function Failure($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$type=$builder.CreateType();$rows=[Collections.Generic.List[object]]::new()
foreach($direction in @('encoder','decoder')){foreach($multiplier in @(1,3)){foreach($countMode in 0..2){foreach($writeMode in 0..2){foreach($length in @(0,1,3,7)){foreach($capacity in @(0,1,3,8)){foreach($offset in @(0,2)){foreach($flush in @($false,$true)){foreach($alias in @($false,$true)){foreach($span in @($false,$true)){foreach($prefill in @($false,$true)){$encoding=[Activator]::CreateInstance($type);foreach($pair in @(@('Multiplier',$multiplier),@('CountMode',$countMode),@('WriteMode',$writeMode))){$type.GetField($pair[0]).SetValue($encoding,[int]$pair[1])};$trace=[Collections.Generic.List[int[]]]::new();$type.GetField('Trace').SetValue($encoding,$trace);$state=if($direction -eq 'encoder'){$encoding.GetEncoder()}else{$encoding.GetDecoder()};if($prefill){if($direction -eq 'encoder'){$state.Fallback=[Text.EncoderReplacementFallback]::new('AB');$state.FallbackBuffer.Fallback([char]0xDC00,0)|Out-Null}else{$state.Fallback=[Text.DecoderReplacementFallback]::new('AB');$state.FallbackBuffer.Fallback([byte[]]@(255),0)|Out-Null}}
$sourceValue=if($direction -eq 'encoder'){,[char[]]::new($length+2)}else{,[byte[]]::new($length+2)};$target=if($direction -eq 'encoder'){,[byte[]]::new($capacity+$offset+2)}else{,[char[]]::new($capacity+$offset+2)};for($i=0;$i -lt $target.Length;$i++){$target[$i]=99};$used=[int[]]@(-7,-8);$completed=[bool[]]@($true);$arguments=[object[]]::new(10);$arguments[0]=$state;$arguments[1]=$sourceValue;$arguments[2]=[int]1;$arguments[3]=[int]$length;$arguments[4]=$target;$arguments[5]=[int]$offset;$arguments[6]=[int]$capacity;$arguments[7]=[bool]$flush;$arguments[8]=$used;$arguments[9]=$completed;$bridge=if($span){$spanBridges[$direction+[string]$alias]}else{$arrayBridges[$direction+[string]$alias]}
